    export default {
        props: {
            isShowSaveBtn: {
                type: Boolean,
                default: false,
            },
            textWhite: {
                type: Boolean,
                default: false,
            },
            insights: {
                type: Boolean,
                default: false,
            },
            popperClass: {
                type: String,
                default: '',
            },
            customLink: String,
        },

        data() {
            return {
                isOpenShare: false,
            };
        },

        mounted() {
            document.addEventListener('scroll', () => {
                this.$refs?.share?.doClose();
            });
        },

        methods: {
            shareLink(media) {
                const mediaLink =
                    media === 'facebook'
                        ? 'https://www.facebook.com/sharer/sharer.php?u='
                        : media === 'twitter'
                        ? 'https://twitter.com/intent/tweet?text='
                        : media === 'instagram'
                        ? 'https://msng.link/o/?'
                        : media === 'linkedin'
                        ? 'https://www.linkedin.com/sharing/share-offsite/?url='
                        : '';
                const url =
                    this.customLink && typeof this.customLink === 'string'
                        ? this.customLink.includes('/insights/')
                            ? mediaLink + window.location.origin + this.customLink
                            : mediaLink + window.location.href + this.customLink
                        : `${mediaLink + encodeURIComponent(window.location.href)}`;
                window.open(url, '_blank');
            },
        },
    };
